const rows = $('Load Videos Ready For FFmpeg').all().map(i => i.json || {});
const products = $('Load Products For Fallback Packshot').all().map(i => i.json || {});

const readyRows = rows.filter(r => r.render_status === 'ready_for_ffmpeg');
const target = readyRows[readyRows.length - 1];
if (!target || !target.video_key) return [];

const matchedProd = products.find(p => p.product_key === target.product_key) || {};
const dePackshotUrl = String(matchedProd.packshot_image_url || '');

let scenes = [];
try { scenes = JSON.parse(target.scenes_json || '[]'); } catch (e) { scenes = []; }
if (!scenes.length) return [];

const segments = [];
for (let i = 0; i < scenes.length; i++) {
  const s = scenes[i] || {};
  const mediaUrl = s.generated_clip_url || s.generated_image_url || dePackshotUrl;
  if (!mediaUrl) return [];
  const mediaType = s.generated_clip_url ? 'video' : 'image';
  segments.push({ type: mediaType, url: mediaUrl, duration: 4.6 });
  if (i === scenes.length - 1) segments.push({ type: mediaType, url: mediaUrl, duration: 4.6 });
}

const pKey = String(target.product_key || '').toLowerCase();
const aKey = String(target.avatar_key || '').toLowerCase();
const isBeautyStyleHealth = /beauty|skin|style|health|medicube|collagen|biodance|sarah|mia/.test(pKey + ' ' + aKey);

const HFTOK = $env.HF_TOKEN || '';
const HF_AUTH = HFTOK ? { Authorization: 'Bearer ' + HFTOK } : {};
const ttsDebug = [];
const errStr = e => { try { return JSON.stringify(e && e.message ? e.message : e).slice(0, 150); } catch (x) { return 'err'; } };
const sleep = ms => new Promise(r => setTimeout(r, ms));

// Hard deadline for EVERY external call — httpRequest timeout does NOT kill an open SSE stream!
const T = (p, ms) => Promise.race([p, new Promise(r => setTimeout(() => r(null), ms))]);

const rawScript = String(target.script_de_full || '')
  .replace(/ae/g, 'ä').replace(/oe/g, 'ö').replace(/ue/g, 'ü')
  .replace(/Ae/g, 'Ä').replace(/Oe/g, 'Ö').replace(/Ue/g, 'Ü')
  .replace(/3-in-1/g, 'drei in eins').replace(/4-in-1/g, 'vier in eins')
  .replace(/7-in-1/g, 'sieben in eins').replace(/8-in-1/g, 'acht in eins')
  .replace(/\bEUR\b/g, 'Euro');

const stitchTask = (async () => {
  let url = '';
  try {
    const mid = Math.ceil(segments.length / 2);
    const [part1, part2] = await Promise.all([
      T(this.helpers.httpRequest({
        method: 'POST', url: 'https://ffmpeg.mafrapi.eu/api/ffmpeg/slideshow',
        headers: { 'Content-Type': 'application/json', 'User-Agent': 'Mozilla/5.0' },
        body: JSON.stringify({ segments: segments.slice(0, mid), imageDuration: 4.6, transition: 0.25 }),
        timeout: 80000
      }), 90000),
      T(this.helpers.httpRequest({
        method: 'POST', url: 'https://ffmpeg.mafrapi.eu/api/ffmpeg/slideshow',
        headers: { 'Content-Type': 'application/json', 'User-Agent': 'Mozilla/5.0' },
        body: JSON.stringify({ segments: segments.slice(mid), imageDuration: 4.6, transition: 0.25 }),
        timeout: 80000
      }), 90000)
    ]);
    const u1 = part1 && part1.reel_url;
    const u2 = part2 && part2.reel_url;
    if (u1 && u2) {
      const joined = await T(this.helpers.httpRequest({
        method: 'POST', url: 'https://ffmpeg.mafrapi.eu/api/ffmpeg/slideshow',
        headers: { 'Content-Type': 'application/json', 'User-Agent': 'Mozilla/5.0' },
        body: JSON.stringify({
          segments: [
            { type: 'video', url: u1, duration: mid * 4.5 },
            { type: 'video', url: u2, duration: (segments.length - mid) * 4.5 }
          ],
          imageDuration: 4.6, transition: 0.2
        }),
        timeout: 70000
      }), 80000);
      if (joined && joined.reel_url) url = String(joined.reel_url);
    }
  } catch (e) {}
  return url;
})();

const splitChunks = () => {
  let textChunks = [];
  if (rawScript.includes('|||')) {
    textChunks = rawScript.split('|||').map(c => c.trim()).filter(Boolean);
  } else {
    const sents = rawScript.split(/(?<=[.!?])\s+/).filter(Boolean);
    let cur = '';
    for (const st of sents) {
      if ((cur + ' ' + st).trim().length <= 210) cur = (cur + ' ' + st).trim();
      else { if (cur) textChunks.push(cur); cur = st; }
    }
    if (cur) textChunks.push(cur);
  }
  return textChunks;
};

const edgeTtsOnce = async (eh) => {
  const edgeVoice = isBeautyStyleHealth
    ? 'de-DE-SeraphinaMultilingualNeural - de-DE (Female)'
    : 'de-DE-FlorianMultilingualNeural - de-DE (Male)';
  const cleanFullText = rawScript.replace(/\s*\|\|\|\s*/g, ' ').replace(/\s+/g, ' ').trim();
  const eCall = await T(this.helpers.httpRequest({
    method: 'POST', url: 'https://' + eh + '/gradio_api/call/tts_interface',
    headers: { 'Content-Type': 'application/json', ...HF_AUTH },
    body: JSON.stringify({ data: [cleanFullText, edgeVoice, 6, 0] }),
    timeout: 12000
  }), 15000);
  const eObj = typeof eCall === 'string' ? JSON.parse(eCall) : eCall;
  if (!eObj || !eObj.event_id) return null;
  const eSse = await T(this.helpers.httpRequest({
    method: 'GET', url: 'https://' + eh + '/gradio_api/call/tts_interface/' + eObj.event_id,
    headers: HF_AUTH, timeout: 25000
  }), 30000);
  if (!eSse) return null;
  for (const line of String(eSse).split('\n')) {
    if (line.startsWith('data: ') && line.trim() !== 'data: null') {
      const d = JSON.parse(line.slice(6));
      if (Array.isArray(d) && d[0] && d[0].url) {
        const mp3Buf = Buffer.from(await T(this.helpers.httpRequest({
          method: 'GET', url: d[0].url, headers: HF_AUTH, encoding: 'arraybuffer', timeout: 20000
        }), 25000));
        if (mp3Buf && mp3Buf.length > 1000) {
          return await this.helpers.prepareBinaryData(mp3Buf, 'voice_de.mp3', 'audio/mpeg');
        }
      }
    }
  }
  return null;
};

// Retry: 2 rounds x all hosts with 5s pause between rounds — catches transient queue stalls
const edgeTts = async () => {
  const edgeHosts = ['innoai-edge-tts-text-to-speech.hf.space', 'cpuai-edge-tts-text-to-speech.hf.space'];
  for (let round = 0; round < 2; round++) {
    if (round > 0) await sleep(5000);
    for (const eh of edgeHosts) {
      try {
        const b = await edgeTtsOnce(eh);
        if (b) return b;
        ttsDebug.push(eh.slice(0, 12) + ' r' + round + ': no-audio');
      } catch (e) { ttsDebug.push(eh.slice(0, 12) + ' r' + round + ': ' + errStr(e)); }
    }
  }
  return null;
};

const chatterbox = async (refFileObj) => {
  if (!refFileObj) return null;
  const sp = 'resembleai-chatterbox-multilingual-tts.hf.space';
  const pcmParts = [];
  let wavHeaderTemplate = null;
  for (const chunk of splitChunks()) {
    let chunkOk = false;
    try {
      const callResp = await T(this.helpers.httpRequest({
        method: 'POST', url: 'https://' + sp + '/gradio_api/call/generate_tts_audio',
        headers: { 'Content-Type': 'application/json', ...HF_AUTH },
        body: JSON.stringify({ data: [chunk, 'de', refFileObj, 0.72, 0.8, 42, 0.05] }),
        timeout: 8000
      }), 12000);
      const callObj = typeof callResp === 'string' ? JSON.parse(callResp) : callResp;
      if (callObj && callObj.event_id) {
        const sseText = await T(this.helpers.httpRequest({
          method: 'GET', url: 'https://' + sp + '/gradio_api/call/generate_tts_audio/' + callObj.event_id,
          headers: HF_AUTH, timeout: 22000
        }), 30000);
        if (sseText) {
          for (const line of String(sseText).split('\n')) {
            if (line.startsWith('data: ') && line.trim() !== 'data: null') {
              const d = JSON.parse(line.slice(6));
              if (Array.isArray(d) && d[0] && d[0].url) {
                const wavBuf = Buffer.from(await T(this.helpers.httpRequest({
                  method: 'GET', url: d[0].url, headers: HF_AUTH, encoding: 'arraybuffer', timeout: 12000
                }), 15000));
                if (wavBuf && wavBuf.length > 44) {
                  if (!wavHeaderTemplate) wavHeaderTemplate = wavBuf.slice(0, 44);
                  pcmParts.push(wavBuf.slice(44));
                  pcmParts.push(Buffer.alloc(8640));
                  chunkOk = true;
                }
              }
            }
          }
        }
      }
    } catch (e) { ttsDebug.push('cb-chunk: ' + errStr(e)); }
    if (!chunkOk) return null;
  }
  if (!wavHeaderTemplate || !pcmParts.length) return null;
  const totalPcm = Buffer.concat(pcmParts);
  const finalWav = Buffer.concat([Buffer.from(wavHeaderTemplate), totalPcm]);
  finalWav.writeUInt32LE(36 + totalPcm.length, 4);
  finalWav.writeUInt32LE(totalPcm.length, 40);
  return await this.helpers.prepareBinaryData(finalWav, 'voice_de.wav', 'audio/wav');
};

const builtinChatterboxRef = async () => {
  const sp = 'resembleai-chatterbox-multilingual-tts.hf.space';
  const refLang = isBeautyStyleHealth ? 'sv' : 'nl';
  try {
    const langCall = await T(this.helpers.httpRequest({
      method: 'POST', url: 'https://' + sp + '/gradio_api/call/on_language_change',
      headers: { 'Content-Type': 'application/json', ...HF_AUTH },
      body: JSON.stringify({ data: [refLang, null, ''] }),
      timeout: 8000
    }), 12000);
    const langObj = typeof langCall === 'string' ? JSON.parse(langCall) : langCall;
    if (!langObj || !langObj.event_id) return null;
    const langSse = await T(this.helpers.httpRequest({
      method: 'GET', url: 'https://' + sp + '/gradio_api/call/on_language_change/' + langObj.event_id,
      headers: HF_AUTH, timeout: 10000
    }), 14000);
    if (!langSse) return null;
    for (const line of String(langSse).split('\n')) {
      if (line.startsWith('data: ') && line.trim() !== 'data: null') {
        const parsed = JSON.parse(line.slice(6));
        if (Array.isArray(parsed) && parsed[0]) return parsed[0];
      }
    }
  } catch (e) { ttsDebug.push('cb-ref: ' + errStr(e)); }
  return null;
};

const luisaUploadedRef = () => {
  try {
    const items = $('Upload Luisa Ref To HF').all() || [];
    const upResp = (items[0] || {}).json;
    let upPath = '';
    if (typeof upResp === 'string' && upResp.startsWith('/')) upPath = upResp;
    else {
      const upArr = typeof upResp === 'string' ? JSON.parse(upResp) : upResp;
      upPath = Array.isArray(upArr) ? upArr[0] : (upArr && upArr.files && upArr.files[0]);
      if (upPath && upPath.json) upPath = upPath.json;
    }
    if (upPath && String(upPath).startsWith('/')) {
      return {
        path: String(upPath),
        url: 'https://resembleai-chatterbox-multilingual-tts.hf.space/gradio_api/file=' + String(upPath),
        orig_name: 'luisa_ref.mp3',
        mime_type: 'audio/mpeg',
        size: null,
        is_stream: false,
        meta: { _type: 'gradio.FileData' }
      };
    }
    ttsDebug.push('luisa-path: unexpected shape ' + JSON.stringify(upResp).slice(0, 100));
  } catch (e) { ttsDebug.push('luisa-path: ' + errStr(e)); }
  return null;
};

const ttsTask = (async () => {
  let vBin = null;
  let provider = 'none';
  try {
    if (isBeautyStyleHealth) {
      const luisaRef = luisaUploadedRef();
      if (luisaRef) {
        vBin = await chatterbox(luisaRef);
        if (vBin) provider = 'hf-chatterbox-clone-luisa-de:luisa_clone (female)';
      } else {
        ttsDebug.push('luisa-ref: upload returned no path');
      }
      if (!vBin) { vBin = await edgeTts(); if (vBin) provider = 'hf-edge-tts-de:seraphina_de (female)'; }
      if (!vBin) {
        const ref = await builtinChatterboxRef();
        if (ref) { vBin = await chatterbox(ref); if (vBin) provider = 'hf-chatterbox-multilingual-de:sv_f (female)'; }
      }
    } else {
      vBin = await edgeTts();
      if (vBin) provider = 'hf-edge-tts-de:florian_de (male)';
      if (!vBin) {
        const ref = await builtinChatterboxRef();
        if (ref) { vBin = await chatterbox(ref); if (vBin) provider = 'hf-chatterbox-multilingual-de:nl_m (male)'; }
      }
    }
  } catch (e) { ttsDebug.push('ttsTask-fatal: ' + errStr(e)); }
  return { vBin, provider };
})();

const [preStitchedUrl, ttsRes] = await Promise.all([stitchTask, ttsTask]);
const voiceBinary = ttsRes.vBin;
const ttsProviderUsed = ttsRes.provider;

if (!voiceBinary) {
  throw new Error('German TTS voiceover generation failed on all Hugging Face tiers. Debug: ' + ttsDebug.join(' | '));
}

return [{
  json: {
    ...target,
    pre_stitched_url: preStitchedUrl,
    tts_provider_used: ttsProviderUsed,
    tts_debug: ttsDebug.join(' | '),
    slideshow_body: JSON.stringify({
      segments: preStitchedUrl ? [{ type: 'video', url: preStitchedUrl, duration: 38.0 }] : segments,
      imageDuration: 4.6,
      transition: 0.25
    })
  },
  binary: { voice: voiceBinary }
}];

const prev = $('Prepare 38s Slideshow & HF TTS Voiceover').first() || {};
const stitched = $input.first()?.json || {};
const stitchedUrl = String(stitched.reel_url || prev.json?.pre_stitched_url || '');
const bgmUrl = 'https://raw.githubusercontent.com/gitbixxs/Music/main/conner-silicon-valley-drive-494293.mp3';

let fallbackMixedUrl = stitchedUrl;
if (stitchedUrl && (!prev.binary || !prev.binary.voice)) {
  try {
    const mixResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://ffmpeg.mafrapi.eu/api/ffmpeg/mix-music',
      headers: { 'Content-Type': 'application/json', 'User-Agent': 'Mozilla/5.0' },
      body: JSON.stringify({ videoUrl: stitchedUrl, musicUrl: bgmUrl, musicVolume: 0.25 }),
      timeout: 60000
    });
    if (mixResp && mixResp.reel_url) fallbackMixedUrl = mixResp.reel_url;
  } catch (e) {}
}

return [{
  json: {
    ...(prev.json || {}),
    stitched_url: stitchedUrl,
    fallback_mixed_url: fallbackMixedUrl
  },
  binary: prev.binary || {}
}];

const prev = $('Restore HF Voice Binary').first()?.json || {};
const mixedItem = $input.first() || {};
const muxedItem = $('FFmpeg Mux HF Voiceover Into Video').first() || {};

let videoBinary = mixedItem.binary?.video || muxedItem.binary?.baseVideo || null;
if (!videoBinary && prev.fallback_mixed_url) {
  try {
    const dl = await this.helpers.httpRequest({
      method: 'GET',
      url: prev.fallback_mixed_url,
      headers: { 'User-Agent': 'Mozilla/5.0' },
      encoding: 'arraybuffer',
      timeout: 60000
    });
    videoBinary = await this.helpers.prepareBinaryData(Buffer.from(dl), 'video.mp4', 'video/mp4');
  } catch (e) {}
}

let scenes = [];
try {
  scenes = JSON.parse(prev.scenes_json || '[]');
} catch (e) {
  scenes = [];
}

function fmt(sec) {
  sec = Math.max(0, Number(sec) || 0);
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  const s = Math.floor(sec % 60);
  const cs = Math.floor((sec - Math.floor(sec)) * 100);
  return h + ':' + String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0') + '.' + String(cs).padStart(2, '0');
}

function wrapWords(text, maxChars = 20) {
  const words = String(text || '').replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);
  const lines = [];
  let cur = '';
  for (const w of words) {
    const cand = cur ? cur + ' ' + w : w;
    if (cand.length <= maxChars) {
      cur = cand;
    } else {
      if (cur) lines.push(cur);
      cur = w;
    }
  }
  if (cur) lines.push(cur);
  return lines.join('\\N');
}

const header = [
  '[Script Info]',
  'Title: TikTok Shop 38s Clean Bold Subtitles',
  'ScriptType: v4.00+',
  'WrapStyle: 0',
  'PlayResX: 1080',
  'PlayResY: 1920',
  '',
  '[V4+ Styles]',
  'Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding',
  'Style: BadgeHook,DejaVu Sans,66,&H0000D7FF,&H0000D7FF,&H00000000,&H80000000,-1,0,0,0,100,100,1,0,1,7,3,8,120,120,200,1',
  'Style: BadgeHero,DejaVu Sans,68,&H0066FF00,&H0066FF00,&H00000000,&H80000000,-1,0,0,0,100,100,1,0,1,7,3,8,120,120,200,1',
  'Style: BadgeCta,DejaVu Sans,70,&H000088FF,&H000088FF,&H00000000,&H80000000,-1,0,0,0,100,100,1,0,1,8,3,8,120,120,200,1',
  'Style: SubHook,DejaVu Sans,58,&H00FFFFFF,&H0000D7FF,&H00000000,&H80000000,-1,0,0,0,100,100,0,0,1,6,3,2,120,120,460,1',
  'Style: SubHero,DejaVu Sans,58,&H00B8FF99,&H0066FF00,&H00000000,&H80000000,-1,0,0,0,100,100,0,0,1,6,3,2,120,120,460,1',
  'Style: SubCta,DejaVu Sans,64,&H0000D7FF,&H000088FF,&H00000000,&H80000000,-1,0,0,0,100,100,0,0,1,7,3,2,120,120,380,1',
  '',
  '[Events]',
  'Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text'
].join('\n') + '\n';

let events = '';
let t = 0;

for (let i = 0; i < scenes.length; i++) {
  const s = scenes[i] || {};
  const isLast = (i === scenes.length - 1);
  const dur = isLast ? 8.5 : 4.35;
  const start = t;
  const end = t + dur;
  t = end;

  const role = String(s.role || '');
  const badgeStyle = role === 'hook' ? 'BadgeHook' : (isLast || role === 'cta') ? 'BadgeCta' : 'BadgeHero';
  const subStyle = role === 'hook' ? 'SubHook' : (isLast || role === 'cta') ? 'SubCta' : 'SubHero';

  const badgeText = wrapWords(String(s.overlay_badge || '').toUpperCase(), 18);
  if (badgeText) {
    events += 'Dialogue: 1,' + fmt(start + 0.05) + ',' + fmt(end - 0.05) + ',' + badgeStyle + ',,0,0,0,,' + badgeText + '\n';
  }

  const words = String(s.spoken_text || '').replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);
  const mid = Math.ceil(words.length / 2);
  const part1 = wrapWords(words.slice(0, mid).join(' '), 20);
  const part2 = wrapWords(words.slice(mid).join(' '), 20);
  const halfDur = dur / (part2 ? 2 : 1);

  if (part1) {
    events += 'Dialogue: 0,' + fmt(start) + ',' + fmt(start + halfDur) + ',' + subStyle + ',,0,0,0,,' + part1 + '\n';
  }
  if (part2) {
    events += 'Dialogue: 0,' + fmt(start + halfDur) + ',' + fmt(end) + ',' + subStyle + ',,0,0,0,,' + part2 + '\n';
  }
}

const assContent = header + events;
const subtitlesBinary = await this.helpers.prepareBinaryData(Buffer.from(assContent, 'utf8'), 'clean_subtitles.ass', 'text/x-ssa');

const binaries = { subtitles: subtitlesBinary };
if (videoBinary) {
  binaries.video = videoBinary;
}

return [{
  json: {
    ...prev,
    has_mixed_video: Boolean(videoBinary)
  },
  binary: binaries
}];

const presign = $input.first()?.json || {};
const subbed = $('FFmpeg Burn Clean ASS Subtitles').first() || {};
return [{
  json: presign,
  binary: subbed.binary || {}
}];

const prev = $('Restore HF Voice Binary').first()?.json || {};
const presign = $('Zernio Presign Video').first()?.json || {};
const reelUrl = String(presign.publicUrl || presign.url || '');

const caption = String(prev.caption_de || 'Wann hast du das letzte Mal deine AirPods & Tastatur richtig gereinigt? Dieses 7-in-1 Elektronik & AirPods Reinigungs-Set bekommt jede Ritze sauber! Unten links im orangenen Warenkorb verlinkt. #airpodsreinigen #techhacks #tastaturreinigen #gadgets #tiktokshopde #bizpunk72');

const isDirectPublish = Boolean(prev.direct_publish);

const zernioBody = {
  content: caption,
  publishNow: true,
  platforms: [
    {
      platform: 'tiktok',
      accountId: '6a99599b77555aae01ce4ec4'
    }
  ],
  mediaItems: reelUrl ? [{ type: 'video', url: reelUrl }] : [],
  tiktokSettings: {
    draft: !isDirectPublish,
    is_ai_generated: true,
    privacy_level: 'PUBLIC_TO_EVERYONE',
    allow_comment: true,
    allow_duet: true,
    allow_stitch: true,
    content_preview_confirmed: true,
    express_consent_given: true
  }
};

return [{
  json: {
    ...prev,
    final_video_url: reelUrl,
    zernio_body: JSON.stringify(zernioBody)
  }
}];

const prev = $('Prepare Zernio TikTok Draft Payload').first()?.json || {};
const zResp = $input.first()?.json || {};
const postObj = zResp.post || zResp.data || zResp || {};
const zernioId = String(postObj._id || zResp.post_id || zResp.id || 'draft_uploaded');
const status = zResp.error ? 'failed: ' + String(zResp.error) : 'draft_in_inbox';

return [{
  json: {
    ...prev,
    zernio_post_id: zernioId,
    publish_status: status
  }
}];
